@import "@fontsource-variable/hanken-grotesk";

/* Light (faithful): white page, warm near-black ink, one light grey for every secondary line
   (nav, section heads, categories), a #ddd hairline above the footer. No accent colour. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.218 0.004 106);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.218 0.004 106);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.218 0.004 106);
  --primary: oklch(0.218 0.004 106);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.955 0 0);
  --secondary-foreground: oklch(0.218 0.004 106);
  --muted: oklch(0.945 0.002 106);
  --muted-foreground: oklch(0.749 0 0);
  --accent: oklch(0.955 0 0);
  --accent-foreground: oklch(0.218 0.004 106);
  --destructive: oklch(0.56 0.19 28);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.902 0 0);
  --input: oklch(0.902 0 0);
  --ring: oklch(0.218 0.004 106);
  --highlight: oklch(0.749 0 0);
  --highlight-foreground: oklch(0.218 0.004 106);
  --glow: oklch(0.88 0.004 106);
  --chart-1: oklch(0.218 0.004 106);
  --chart-2: oklch(0.45 0.004 106);
  --chart-3: oklch(0.62 0 0);
  --chart-4: oklch(0.749 0 0);
  --chart-5: oklch(0.88 0 0);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.218 0.004 106);
  --sidebar-primary: oklch(0.218 0.004 106);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.955 0 0);
  --sidebar-accent-foreground: oklch(0.218 0.004 106);
  --sidebar-border: oklch(0.902 0 0);
  --sidebar-ring: oklch(0.218 0.004 106);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 90rem;
  --page-gutter: 1.5rem;
  --section-y: 3rem;
}

@media (min-width: 48rem) {
  :root {
    --page-gutter: 2rem;
    --section-y: 5rem;
  }
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 2.5rem;
    --section-y: 8rem;
  }
}

/* Dark (sibling): warm near-black page, off-white ink, the same mid grey for secondary lines. */
.dark {
  --background: oklch(0.2 0.004 106);
  --foreground: oklch(0.96 0.002 106);
  --card: oklch(0.2 0.004 106);
  --card-foreground: oklch(0.96 0.002 106);
  --popover: oklch(0.24 0.004 106);
  --popover-foreground: oklch(0.96 0.002 106);
  --primary: oklch(0.96 0.002 106);
  --primary-foreground: oklch(0.2 0.004 106);
  --secondary: oklch(0.27 0.004 106);
  --secondary-foreground: oklch(0.96 0.002 106);
  --muted: oklch(0.27 0.004 106);
  --muted-foreground: oklch(0.6 0 0);
  --accent: oklch(0.27 0.004 106);
  --accent-foreground: oklch(0.96 0.002 106);
  --destructive: oklch(0.66 0.18 28);
  --destructive-foreground: oklch(0.96 0.002 106);
  --border: oklch(0.96 0.002 106 / 14%);
  --input: oklch(0.96 0.002 106 / 20%);
  --ring: oklch(0.96 0.002 106);
  --highlight: oklch(0.6 0 0);
  --highlight-foreground: oklch(0.96 0.002 106);
  --glow: oklch(0.32 0.004 106);
  --chart-1: oklch(0.96 0.002 106);
  --chart-2: oklch(0.8 0 0);
  --chart-3: oklch(0.6 0 0);
  --chart-4: oklch(0.45 0 0);
  --chart-5: oklch(0.32 0 0);
  --sidebar: oklch(0.23 0.004 106);
  --sidebar-foreground: oklch(0.96 0.002 106);
  --sidebar-primary: oklch(0.96 0.002 106);
  --sidebar-primary-foreground: oklch(0.2 0.004 106);
  --sidebar-accent: oklch(0.27 0.004 106);
  --sidebar-accent-foreground: oklch(0.96 0.002 106);
  --sidebar-border: oklch(0.96 0.002 106 / 14%);
  --sidebar-ring: oklch(0.96 0.002 106);
}
